package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	const digs = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
	for sc.Scan() {
		f := strings.Fields(sc.Text())
		if len(f) < 3 {
			continue
		}
		var from, to uint64
		fmt.Sscan(f[1], &from)
		fmt.Sscan(f[2], &to)
		var v uint64
		for _, c := range strings.ToUpper(f[0]) {
			d := strings.IndexRune(digs, c)
			v = v*from + uint64(d)
		}
		if v == 0 {
			fmt.Fprintln(w, "0")
			continue
		}
		var b []byte
		for v > 0 {
			b = append(b, digs[v%to])
			v /= to
		}
		for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
			b[i], b[j] = b[j], b[i]
		}
		fmt.Fprintln(w, string(b))
	}
}
